<?php
require_once 'db.php';
require_admin();
$q=trim($_GET['q']??'');
$brand=trim($_GET['brand']??'');
$service=trim($_GET['service']??'');
$date=trim($_GET['date']??'');
$sql="SELECT p.*,u.full_name,v.vehicle_number FROM predictions p JOIN users u ON p.user_id=u.user_id JOIN vehicles v ON p.vehicle_id=v.vehicle_id WHERE p.is_deleted_by_admin=0";
$types='';
$params=[];
if($q!==''){
    $sql.=' AND (u.full_name LIKE ? OR p.vehicle_model LIKE ? OR v.vehicle_number LIKE ?)';
    $like='%'.$q.'%';
    array_push($params,$like,$like,$like);
    $types.='sss';
}if($brand!==''){
    $sql.=' AND p.vehicle_brand=?';
    $params[]=$brand;
    $types.='s';
}if($service!==''){
    $sql.=' AND p.service_type=?';
    $params[]=$service;
    $types.='s';
}if($date!==''){
    $sql.=' AND DATE(p.prediction_date)=?';
    $params[]=$date;
    $types.='s';
}$sql.=' ORDER BY p.prediction_date DESC';
$s=$conn->prepare($sql);
if($params)$s->bind_param($types,...$params);
$s->execute();
$r=$s->get_result();
$stats=$conn->query("SELECT COUNT(*) total,AVG(predicted_cost) cost,AVG(predicted_duration_hours) duration,AVG(predicted_delay_probability) delay FROM predictions WHERE is_deleted_by_admin=0")->fetch_assoc();
include 'header.php';
?>
<section class="admin-page-head"><div class="container"><div class="kicker">Administration Panel</div><h1>Prediction <span class="gold">Management</span></h1><p>View all AI-generated predictions and filter records by vehicle brand, service type, and prediction date range.</p></div></section>
<section class="section"><div class="container"><div class="admin-count reveal"><strong><?= (int) $stats['total'] ?></strong><span>Prediction Records Found</span></div><div class="admin-split reveal"><aside class="admin-photo"><img src="images/admin/prediction-management.jpg" alt="Dark vehicle prediction analytics"><div class="admin-photo-copy"><h3>Prediction Analytics</h3><p>Filter prediction records and review AI outputs generated by users across different vehicle brands and service types.</p></div></aside><div class="admin-records"><h2>Prediction Records</h2><p class="muted">Use filters to find specific prediction records.</p><form class="admin-filter-box" method="get"><div class="row g-2"><div class="col-md-6"><label class="form-label">Filter By Brand</label><input class="form-control" name="brand" value="<?= e($brand) ?>" placeholder="All Brands"></div><div class="col-md-6"><label class="form-label">Filter By Service Type</label><input class="form-control" name="service" value="<?= e($service) ?>" placeholder="All Services"></div><div class="col-md-6"><label class="form-label">Prediction Date</label><input class="form-control" type="date" name="date" value="<?= e($date) ?>"></div><div class="col-md-6"><label class="form-label">Search User / Model / Plate</label><input class="form-control" name="q" value="<?= e($q) ?>" placeholder="Search..."></div><div class="col-12 d-flex gap-2 mt-3"><button class="btn btn-gold">Apply Filters</button><a class="btn btn-outline-lux" href="admin_predictions.php">Reset</a></div></div></form><div class="table-shell"><table class="lux-table"><thead><tr><th>User</th><th>Vehicle</th><th>Service</th><th>Cost</th><th>Duration</th><th>Delay</th><th>Date</th><th>Action</th></tr></thead><tbody><?php while ($row = $r->fetch_assoc()): ?><tr><td><?= e($row['full_name']) ?></td><td><?= e($row['vehicle_brand'].' '.$row['vehicle_model']) ?></td><td><?= e($row['service_type']) ?></td><td><span class="pill gold">Rs. <?= number_format($row['predicted_cost'],0) ?></span></td><td><span class="pill blue"><?= number_format($row['predicted_duration_hours'],1) ?> Hours</span></td><td><span class="pill gold"><?= number_format($row['predicted_delay_probability'],1) ?>%</span></td><td><?= e($row['prediction_date']) ?></td><td><a class="btn-danger-lux" href="actions/delete_prediction_admin.php?id=<?= $row['prediction_id'] ?>" data-confirm="Delete this prediction from admin view?">Delete</a></td></tr><?php endwhile; ?></tbody></table></div><div class="insight-box"><strong>Prediction Management Insight</strong><p>This page helps admin review prediction activity, filter AI-generated records, analyse popular vehicle brands, and identify commonly requested service types.</p></div></div></div></div></section><?php include 'footer.php'; ?>